// Package override builds the text of a generated docker-compose.override.yml.
package override

import (
	"fmt"
	"strings"
)

// Marker is the comment that identifies a docker-compose.override.yml as
// having been generated by this tool. It must stay byte-for-byte identical
// to the original compose-worktree-override shell function's marker, since
// existing override files on disk are guarded by this exact string.
const Marker = "# generated by compose-worktree-override"

// Service is one service's resolved override: the container_name to set
// (empty if none) and the fully-formed `"host:container"` port lines to
// emit (nil if the service has no ports to override).
type Service struct {
	Name          string
	ContainerName string
	HasPorts      bool
	Ports         []string
}

// Build renders the override file contents for the given services, in the
// order provided. It returns "" if none of the services have anything to
// override.
func Build(services []Service) string {
	var any bool
	for _, s := range services {
		if s.ContainerName != "" || s.HasPorts {
			any = true
			break
		}
	}
	if !any {
		return ""
	}

	var b strings.Builder
	b.WriteString(Marker + "\n")
	b.WriteString("services:\n")

	for _, s := range services {
		if s.ContainerName == "" && !s.HasPorts {
			continue
		}

		fmt.Fprintf(&b, "  %s:\n", s.Name)

		if s.ContainerName != "" {
			fmt.Fprintf(&b, "    container_name: %s\n", s.ContainerName)
		}

		if s.HasPorts {
			// docker compose merges (concatenates) list-typed keys across
			// override files by default, so without !override the
			// original, un-namespaced ports would still be exposed
			// alongside the reassigned ones (Compose 2.24+).
			b.WriteString("    ports: !override\n")
			for _, p := range s.Ports {
				fmt.Fprintf(&b, "      - %q\n", p)
			}
		}
	}

	return b.String()
}
